// pnpm gen:events (BL-0024): generate packages/shared-types/src/events.gen.ts from the event
// catalogue of doc 11 section 9 (normative per 00a D6). One table row lists one or more event
// names (first column) and the keys of `props` (second column, or "none"). The generated file is
// committed; CI regenerates it and fails on any difference. Never edit it by hand.
import { readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..", "..");
const DOC = path.join(ROOT, "polymath-app-spec", "docs", "11-evaluation-and-experiment-plan.md");
const OUT = path.join(ROOT, "packages", "shared-types", "src", "events.gen.ts");
const NAME = /^[a-z0-9_.]{1,64}$/; // the same rule as api.openapi.yaml ClientEvent.name and events.name

/** Returns {name: [prop keys]} from the tables between "## 9." and "## 10.". */
export function parseCatalogue(markdown) {
  const start = markdown.search(/^## 9\. Event catalogue/m);
  const end = markdown.search(/^## 10\. /m);
  if (start < 0 || end < start) throw new Error("doc 11 section 9 not found");
  const events = {};
  for (const line of markdown.slice(start, end).split("\n")) {
    if (!line.startsWith("| `")) continue;
    const cells = line.split("|").map((c) => c.trim());
    const names = [...(cells[1] ?? "").matchAll(/`([^`]+)`/g)].map((m) => m[1] ?? "");
    const keys = [...(cells[2] ?? "").matchAll(/`([^`]+)`/g)].map((m) => m[1] ?? "");
    for (const name of names) {
      if (!NAME.test(name)) throw new Error(`event name "${name}" breaks ${NAME}`);
      if (name in events) throw new Error(`event "${name}" is listed twice`);
      events[name] = keys;
    }
  }
  if (Object.keys(events).length < 40) throw new Error("the catalogue parsed to too few events");
  return events;
}

export function render(events) {
  const body = Object.entries(events)
    .map(([name, keys]) => `  ${name}: [${keys.map((k) => JSON.stringify(k)).join(", ")}],`)
    .join("\n");
  return (
    "// GENERATED by pnpm gen:events (tools/gen/gen-events.mjs) from doc 11 section 9. Do not edit by hand.\n" +
    "// Every event of the catalogue with the keys its `props` may carry (plus `client_at`, see EVENT_COMMON_KEYS).\n" +
    `export const EVENT_PROP_KEYS = {\n${body}\n} as const;\n\n` +
    "export type EventName = keyof typeof EVENT_PROP_KEYS;\n" +
    "export const EVENT_NAMES = Object.keys(EVENT_PROP_KEYS) as EventName[];\n" +
    "/** Keys any event may carry besides its own: the client's clock for an offline event (doc 11 section 9). */\n" +
    'export const EVENT_COMMON_KEYS = ["client_at"] as const;\n'
  );
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  writeFileSync(OUT, render(parseCatalogue(readFileSync(DOC, "utf8"))));
  console.log("wrote packages/shared-types/src/events.gen.ts");
}
